export type ObjName = keyof typeof OBJ;

/** One object, drawn in currentColor with its second tone in sky (`--ob-accent`). Decorative. */
export function Obj({ name, className = "size-6" }: { name: ObjName; className?: string }) {
  return (
    <svg viewBox="0 0 18 18" aria-hidden className={`infra-obj shrink-0 ${className}`}>
      {OBJ[name]}
    </svg>
  );
}

/**
 * The object tile: solid, a hairline edge and a soft lift, the object centred on it. `lit` rings it in sky (the part
 * in play), `dim` greys it (switched off, not involved). `badge` sits on its lower right corner (a brand mark, a
 * lock, a check).
 */
export function Tile({
  size = 56,
  lit = false,
  dim = false,
  badge,
  className = "",
  style,
  children,
}: {
  size?: number;
  lit?: boolean;
  dim?: boolean;
  badge?: ReactNode;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}) {
  return (
    <span
      data-lit={lit}
      data-dim={dim}
      className={`infra-tile ${className}`}
      style={{ width: size, height: size, borderRadius: Math.round(size * 0.27), ...style }}
    >
      {children}
      {badge && <span className="infra-badge">{badge}</span>}
    </span>
  );
}

/** A tile with one object on it. */
export function ObjTile({
  name,
  size = 56,
  lit,
  dim,
  badge,
  className = "",
}: {
  name: ObjName;
  size?: number;
  lit?: boolean;
  dim?: boolean;
  badge?: ReactNode;
  className?: string;
}) {
  return (
    <Tile size={size} lit={lit} dim={dim} badge={badge} className={className}>
      <svg viewBox="0 0 18 18" aria-hidden className="infra-obj" style={{ width: Math.round(size * 0.46), height: Math.round(size * 0.46) }}>
        {OBJ[name]}
      </svg>
    </Tile>
  );
}

/** A node's name under its tile (1 to 3 words), with an optional mono detail (a host, a port). */
export function NodeLabel({
  title,
  sub,
  mono = true,
  className = "",
}: {
  title: ReactNode;
  sub?: ReactNode;
  /** The detail in mono (a host, a port, a key type); off for plain words. */
  mono?: boolean;
  className?: string;
}) {
  return (
    <span className={`flex flex-col items-center text-center ${className}`}>
      <span className="text-[13.5px] leading-[18px] font-medium tracking-[-0.02em] whitespace-nowrap text-fg">{title}</span>
      {sub && (
        <span className={`mt-0.5 leading-4 whitespace-nowrap text-mute ${mono ? "font-mono text-[11.5px]" : "text-[12.5px]"}`}>{sub}</span>
      )}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* Stage: an SVG for the wires with HTML tiles placed over it          */
/* ------------------------------------------------------------------ */

export type Pt = [number, number];

/**
 * A diagram's frame: `w` by `h` user units, the SVG (wires, beams) filling it exactly, and the HTML (tiles, labels)
 * placed over it with `at`.
 */
export function Stage({
  w,
  h,
  svg,
  children,
  className = "",
}: {
  w: number;
  h: number;
  svg: ReactNode;
  children?: ReactNode;
  className?: string;
}) {
  return (
    <div className={`relative ${className}`} style={{ aspectRatio: `${w} / ${h}` }}>
      <svg viewBox={`0 0 ${w} ${h}`} className="absolute inset-0 size-full overflow-visible" aria-hidden>
        {svg}
      </svg>
      {children}
    </div>
  );
}

/**
 * Places an HTML element on the stage with the point (x, y) at its anchor: the centre by default, or the centre of
 * its first `top` pixels (a tile whose label hangs below it).
 */
export function at(x: number, y: number, w: number, h: number, top?: number): CSSProperties {
  return {
    position: "absolute",
    left: `${(x / w) * 100}%`,
    top: `${(y / h) * 100}%`,
    transform: top === undefined ? "translate(-50%, -50%)" : `translate(-50%, ${-top / 2}px)`,
  };
}

/** A polyline with its corners rounded off (radius `r`, clamped to each leg). */
export function rounded(points: Pt[], r = 18): string {
  if (points.length < 3) return points.map(([x, y], i) => `${i ? "L" : "M"}${x} ${y}`).join(" ");
  let d = `M${points[0][0]} ${points[0][1]}`;
  for (let i = 1; i < points.length - 1; i++) {
    const [px, py] = points[i - 1];
    const [x, y] = points[i];
    const [nx, ny] = points[i + 1];
    const l1 = Math.hypot(x - px, y - py);
    const l2 = Math.hypot(nx - x, ny - y);
    const rr = Math.min(r, l1 / 2, l2 / 2);
    const ax = x - ((x - px) / l1) * rr;
    const ay = y - ((y - py) / l1) * rr;
    const bx = x + ((nx - x) / l2) * rr;
    const by = y + ((ny - y) / l2) * rr;
    d += ` L${ax.toFixed(2)} ${ay.toFixed(2)} Q${x} ${y} ${bx.toFixed(2)} ${by.toFixed(2)}`;
  }
  const [lx, ly] = points[points.length - 1];
  return `${d} L${lx} ${ly}`;
}

/** A soft S-curve from a to b, leaving and arriving along `axis` ("x": sideways, "y": up or down). */
export function curve(a: Pt, b: Pt, axis: "x" | "y" = "y", k = 0.55): string {
  if (axis === "y") {
    const dy = (b[1] - a[1]) * k;
    return `M${a[0]} ${a[1]} C${a[0]} ${a[1] + dy} ${b[0]} ${b[1] - dy} ${b[0]} ${b[1]}`;
  }
  const dx = (b[0] - a[0]) * k;
  return `M${a[0]} ${a[1]} C${a[0] + dx} ${a[1]} ${b[0] - dx} ${b[1]} ${b[0]} ${b[1]}`;
}

/** The wire class: a 1.5px soft line that follows the theme. */
export const WIRE = "infra-wire";
